using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Reflection;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Controls.Primitives;
using System.Windows.Media;
using System.Windows.Threading;
using System.Web.Script.Serialization;
using Kotoba;

public static class UiSmokeTests {
 static int passed,failed;
 static MainWindow window;
 static string dataDirectory;
 const BindingFlags Flags=BindingFlags.Instance|BindingFlags.NonPublic;
 static T Get<T>(string name) {return (T)typeof(MainWindow).GetField(name,Flags).GetValue(window);}
 static void Set(string name,object value) {typeof(MainWindow).GetField(name,Flags).SetValue(window,value);}
 static object Call(string name,params object[] args) {try{return typeof(MainWindow).GetMethod(name,Flags).Invoke(window,args);}catch(TargetInvocationException e){throw e.InnerException;}}
 static void Check(bool ok,string message) {if(!ok)throw new Exception(message);}
 static IEnumerable<T> All<T>(DependencyObject root) where T:DependencyObject {
  if(root is T)yield return (T)root;
  foreach(object child in LogicalTreeHelper.GetChildren(root))if(child is DependencyObject)foreach(var nested in All<T>((DependencyObject)child))yield return nested;
 }
 static void Click(string caption) {var b=All<Button>((DependencyObject)window.Content).First(x=>(x.Content as string)==caption);b.RaiseEvent(new RoutedEventArgs(ButtonBase.ClickEvent));}
 static void Layout() {var ui=(FrameworkElement)window.Content;ui.Measure(new Size(window.Width,window.Height));ui.Arrange(new Rect(0,0,window.Width,window.Height));ui.UpdateLayout();Check(!window.IsVisible,"test unexpectedly displayed window");Check(Get<object>("source")==null,"test created a native window/hotkey");}
 static void Toggle(string caption,bool value) {var check=All<CheckBox>((DependencyObject)window.Content).First(x=>(x.Content as string)==caption);check.IsChecked=value;check.RaiseEvent(new RoutedEventArgs(ButtonBase.ClickEvent));}
 static Color BackgroundColor(Border border) {return ((SolidColorBrush)border.Background).Color;}
 static Store Store {get{return Get<Store>("store");}}
 static string Snapshot() {return new JavaScriptSerializer().Serialize(Store.Data);}
 static void Reset() {Store.Data=new State();Set("undo",null);Set("query","");Set("starsOnly",false);Set("libraryLevels",null);Set("notice","");Set("view","study");Call("StopSpeech");Call("ApplyAppearance");Call("BuildShell");Call("SelectNext");}
 static void Test(string name,Action work) {try{Reset();work();passed++;Console.WriteLine("PASS "+name);}catch(Exception e){failed++;Console.WriteLine("FAIL "+name+": "+e.Message);}}
 [STAThread] public static void Main() {
  Console.OutputEncoding=System.Text.Encoding.UTF8;
  dataDirectory=Path.Combine(Path.GetTempPath(),"kotoba-ui-"+Guid.NewGuid().ToString("N"));
  var app=new Application {ShutdownMode=ShutdownMode.OnExplicitShutdown};
  try {
   window=new MainWindow(new[]{"--data="+dataDirectory});
   Test("embedded 10641-word vocabulary loads all five levels",()=>{var words=Get<List<Word>>("words");Check(words.Count==10641,"unexpected vocabulary count "+words.Count);Check(words.Select(x=>x.Level).Distinct().Count()==5,"missing JLPT level");Check(words.All(x=>!String.IsNullOrWhiteSpace(x.Reading)),"missing reading");Layout();});
   Test("grading before reveal cannot change progress",()=>{string before=Snapshot();Call("Grade",3);Check(Snapshot()==before,"hidden answer was graded");Check(Get<UniformGrid>("ratings").Children.OfType<Button>().All(x=>!x.IsEnabled),"rating button enabled before reveal");});
   Test("flip reveals answer and enables ratings without grading",()=>{var word=Get<Word>("current");Call("Flip");Check(Get<bool>("revealed"),"reveal state missing");Check(Get<TextBlock>("answer").Text==word.Meaning,"wrong answer");Check(Get<UniformGrid>("ratings").Children.OfType<Button>().All(x=>x.IsEnabled),"ratings disabled after flip");Check(Store.Data.Progress.Count==0,"flip counted review");Layout();});
   Test("grade persists and undo restores word and daily counts",()=>{var word=Get<Word>("current");Call("Flip");Call("Grade",3);string day=DateTime.Now.ToString("yyyy-MM-dd");Check(Store.Data.DailyReviews[day]==1&&Store.Data.DailyNew[day]==1,"grade counters wrong");var loaded=new Store(dataDirectory);Check(loaded.Data.Progress[word.Id].Reviews==1,"grade not persisted");Call("Undo");Check(Get<Word>("current").Id==word.Id,"undo returned wrong card");Check(Store.Data.Progress.Count==0&&Store.Data.DailyReviews.Count==0&&Store.Data.DailyNew.Count==0,"undo did not restore counts");Check(new Store(dataDirectory).Data.Progress.Count==0,"undo not persisted");});
   Test("library search and selection update preview without reviewing",()=>{string before=Snapshot();var target=Get<List<Word>>("words").First(x=>x.Term.Length>1);Click("词库");var box=All<TextBox>((DependencyObject)window.Content).First();box.Text=target.Term;var list=Get<ListBox>("results");Check(list.Items.Count>0,"search returned nothing");list.SelectedIndex=0;var selected=(Word)((ListBoxItem)list.SelectedItem).Tag;Check(Get<TextBlock>("preview").Text.Contains(selected.Term)&&Get<TextBlock>("preview").Text.Contains(selected.Meaning),"selected preview stale");Check(Snapshot()==before,"search altered review state");Layout();});
   Test("opening library card is ungraded practice and shows actual level",()=>{Click("词库");Set("libraryLevels",new[]{1});Call("RefreshLibrary");Get<ListBox>("results").SelectedIndex=0;Call("OpenSelected");Check(Get<bool>("practice")&&Get<bool>("revealed"),"library card not practice");Check(Get<Word>("current").Level==1,"library level filter failed");Check(All<TextBlock>((DependencyObject)window.Content).Any(x=>x.Text=="N1  ·  日语 → 中文"),"card shows wrong level");string before=Snapshot();Call("Grade",4);Check(Snapshot()==before,"practice card changed review state");});
   Test("hide-reading setting conceals clue until flip and saves",()=>{Click("设置");var check=All<CheckBox>((DependencyObject)window.Content).First(x=>(x.Content as string)=="翻面前显示假名提示");check.IsChecked=false;check.RaiseEvent(new RoutedEventArgs(ButtonBase.ClickEvent));Click("背单词");Check(Get<TextBlock>("reading").Text=="","reading clue still visible");Check(!new Store(dataDirectory).Data.Settings.ShowReading,"setting not persisted");Call("Flip");Check(Get<TextBlock>("reading").Text==Get<Word>("current").Reading,"flip did not reveal reading");});
   Test("changing daily limit to zero stops new cards and changing back refills immediately",()=>{Click("设置");All<ComboBox>((DependencyObject)window.Content).First().SelectedItem=0;Click("背单词");Check(Get<Word>("current")==null,"zero limit permits new card");Click("设置");All<ComboBox>((DependencyObject)window.Content).First().SelectedItem=5;Click("背单词");Check(Get<Word>("current")!=null,"return to study left stale empty state");});
   Test("level selector replaces current card and invalidates undo",()=>{Call("Flip");Call("Grade",3);Call("ApplyLevels",new object[]{new[]{1}});Check(Scheduler.SelectedLevels(Store.Data.Settings).SequenceEqual(new[]{1})&&Get<Word>("current").Level==1,"level did not change card");Check(Get<State>("undo")==null,"old-level undo still active");});
   Test("favorite toggle persists without counting review and supports filtering",()=>{var word=Get<Word>("current");Call("ToggleStar");Check(Store.Data.Progress[word.Id].Star&&Store.Data.Progress[word.Id].Reviews==0,"favorite changed learning count");Check(Store.Data.DailyReviews.Count==0,"favorite counted daily review");Check(new Store(dataDirectory).Data.Progress[word.Id].Star,"favorite not persisted");Click("词库");Set("starsOnly",true);Call("RefreshLibrary");Check(Get<ListBox>("results").Items.Count==1,"favorite filter incorrect");});
   Test("undo from settings returns study and retains changed reading preference",()=>{Call("Flip");Call("Grade",3);Click("设置");var check=All<CheckBox>((DependencyObject)window.Content).First(x=>(x.Content as string)=="翻面前显示假名提示");check.IsChecked=false;check.RaiseEvent(new RoutedEventArgs(ButtonBase.ClickEvent));Call("Undo");Check(Get<string>("view")=="study","undo left stale view");Check(!Store.Data.Settings.ShowReading,"undo reverted a later preference");Check(Store.Data.DailyReviews.Count==0,"undo did not restore review counter");Layout();});
   Test("compact mode changes dimensions and remains renderable",()=>{bool was=Store.Data.Settings.Compact;Call("ToggleCompact");Check(Store.Data.Settings.Compact!=was&&window.Width==365&&window.Height==540,"compact dimensions wrong");Layout();Call("ToggleCompact");Check(window.Width==452&&window.Height==700,"expanded dimensions wrong");Layout();});
   Test("failed favorite save rolls back cleanly without null dereference",()=>{var word=Get<Word>("current");Store.Save();using(var held=new FileStream(Store.FilePath,FileMode.Open,FileAccess.Read,FileShare.Read)){Call("ToggleStar");Check(!Store.Data.Progress.ContainsKey(word.Id),"failed favorite save left in-memory mutation");Check(Get<Button>("star").Content.ToString()=="☆","failed favorite save left visual star");}});
   Test("failed grade save leaves card and counters intact",()=>{var word=Get<Word>("current");Store.Save();Call("Flip");using(var held=new FileStream(Store.FilePath,FileMode.Open,FileAccess.Read,FileShare.Read)){Call("Grade",3);Check(Store.Data.Progress.Count==0&&Store.Data.DailyReviews.Count==0,"failed grade mutated data");Check(Get<Word>("current").Id==word.Id&&Get<bool>("revealed"),"failed grade advanced card");}});

   Test("multi-level study selection updates label and persists all levels",()=>{Call("ApplyLevels",new object[]{new[]{5,3}});Check(Scheduler.SelectedLevels(Store.Data.Settings).OrderBy(x=>x).SequenceEqual(new[]{3,5}),"multi-level state missing");Check(new[]{3,5}.Contains(Get<Word>("current").Level),"current card outside selected levels");Check(All<Button>((DependencyObject)window.Content).Any(x=>(x.Content as string)=="N5+N3 ▾"),"selection caption missing levels");Check(Scheduler.SelectedLevels(new Store(dataDirectory).Data.Settings).OrderBy(x=>x).SequenceEqual(new[]{3,5}),"multi-level choice not persisted");Layout();});
   Test("empty level selection preserves current card settings and progress",()=>{Call("ApplyLevels",new object[]{new[]{4,2}});string before=Snapshot();string id=Get<Word>("current").Id;Call("ApplyLevels",new object[]{new int[0]});Check(Snapshot()==before,"empty selection altered saved state");Check(Get<Word>("current").Id==id,"empty selection changed card");Check(!String.IsNullOrWhiteSpace(Get<string>("notice")),"empty selection did not explain rejection");});
   Test("library multi-level filter searches union of selected levels",()=>{Click("词库");Set("libraryLevels",new[]{5,1});Call("RefreshLibrary");var list=Get<ListBox>("results");Check(list.Items.Count>0,"union filter empty");Check(list.Items.Cast<ListBoxItem>().All(x=>new[]{5,1}.Contains(((Word)x.Tag).Level)),"library includes an unselected level");int expected=Get<List<Word>>("words").Count(x=>x.Level==5||x.Level==1);Check(Get<TextBlock>("resultCount").Text.Contains(expected.ToString("N0"))||Get<TextBlock>("resultCount").Text.Contains(expected.ToString()),"union total does not reflect both levels");Set("query",Get<List<Word>>("words").First(x=>x.Level==1).Term);Call("RefreshLibrary");Check(Get<ListBox>("results").Items.Cast<ListBoxItem>().Any(x=>((Word)x.Tag).Level==1),"N1 result unavailable inside union");});
   Test("dark and light theme controls change real card palette and persist",()=>{Click("设置");Click("暗色");Check(Store.Data.Settings.Theme=="Dark"&&Get<bool>("dark"),"dark preference not applied");Check(BackgroundColor(Get<Border>("frame"))==Color.FromRgb(0x15,0x1D,0x30),"dark frame palette not applied");Check(new Store(dataDirectory).Data.Settings.Theme=="Dark","dark mode not persisted");Layout();Click("背单词");Check(((SolidColorBrush)Get<TextBlock>("term").Foreground).Color==Color.FromRgb(0xED,0xF2,0xFF),"study text not recolored");Click("设置");Click("亮色");Check(!Get<bool>("dark")&&BackgroundColor(Get<Border>("frame"))==Color.FromRgb(0xF5,0xF7,0xFC),"light palette did not restore");});
   Test("transparent mode changes background alpha while keeping text opaque",()=>{Click("设置");Toggle("透明背景（文字保持清晰）",true);var slider=All<Slider>((DependencyObject)window.Content).Single();slider.Value=.4;Check(Math.Abs(Store.Data.Settings.BackgroundOpacity-.4)<.001,"opacity slider did not update setting");Check(BackgroundColor(Get<Border>("frame")).A<255,"frame remains opaque");Click("背单词");var term=Get<TextBlock>("term");Check(window.Opacity==1&&((FrameworkElement)window.Content).Opacity==1&&term.Opacity==1,"whole window or text was made translucent");Check(((SolidColorBrush)term.Foreground).Color.A==255,"text brush is translucent");Check(All<Border>((DependencyObject)window.Content).Any(x=>x.Background is SolidColorBrush&&BackgroundColor(x).A>0&&BackgroundColor(x).A<255),"no transparent card background found");Click("设置");Toggle("透明背景（文字保持清晰）",false);Check(BackgroundColor(Get<Border>("frame")).A==255,"disabling transparency did not restore background");Layout();});
   Test("auto speech defaults on but hidden window never schedules playback",()=>{Check(Store.Data.Settings.AutoSpeak,"auto speech is not default");Call("SelectNext");Call("AutoRead");var timer=Get<DispatcherTimer>("autoSpeech");Check(timer==null||!timer.IsEnabled,"hidden window scheduled automatic speech");Click("设置");Toggle("新卡出现时自动发音（R 仍可重播）",false);Check(!new Store(dataDirectory).Data.Settings.AutoSpeak,"auto speech off not saved");Toggle("新卡出现时自动发音（R 仍可重播）",true);Check(new Store(dataDirectory).Data.Settings.AutoSpeak,"auto speech on not saved");Click("背单词");timer=Get<DispatcherTimer>("autoSpeech");Check(timer==null||!timer.IsEnabled,"settings change scheduled hidden speech");Layout();});
   Test("shuffle control and reshuffle preserve progress and chosen levels",()=>{Call("ApplyLevels",new object[]{new[]{5,4}});Call("ToggleStar");string id=Get<Word>("current").Id;Click("设置");Toggle("新词乱序（到期复习仍然优先）",true);Check(Store.Data.Settings.Shuffle&&new Store(dataDirectory).Data.Settings.Shuffle,"shuffle not saved");int seed=Store.Data.Settings.ShuffleSeed;Click("重新洗牌");Check(Store.Data.Settings.ShuffleSeed!=seed,"reshuffle did not replace seed");Check(Store.Data.Progress[id].Star&&Store.Data.Progress[id].Reviews==0,"reshuffle reset progress");Check(Scheduler.SelectedLevels(Store.Data.Settings).OrderBy(x=>x).SequenceEqual(new[]{4,5}),"reshuffle changed levels");Click("背单词");Check(new[]{4,5}.Contains(Get<Word>("current").Level),"shuffled card outside levels");});
   Test("undo retains later theme transparency speech and multi-level preferences",()=>{Call("ApplyLevels",new object[]{new[]{5,4}});Call("Flip");Call("Grade",3);Click("设置");Click("暗色");Toggle("透明背景（文字保持清晰）",true);All<Slider>((DependencyObject)window.Content).Single().Value=.5;Toggle("新卡出现时自动发音（R 仍可重播）",false);Click("Windows 备用");Call("Undo");Check(Get<string>("view")=="study"&&Store.Data.DailyReviews.Count==0,"undo did not return restored study state");var s=Store.Data.Settings;Check(s.Theme=="Dark"&&s.Transparent&&Math.Abs(s.BackgroundOpacity-.5)<.001&&!s.AutoSpeak&&s.VoiceBackend=="Windows","undo reverted new preferences");Check(Scheduler.SelectedLevels(s).OrderBy(x=>x).SequenceEqual(new[]{4,5}),"undo reverted level selection");Check(Get<bool>("dark")&&BackgroundColor(Get<Border>("frame")).A<255,"undo lost theme rendering");var loaded=new Store(dataDirectory).Data.Settings;Check(loaded.Theme=="Dark"&&loaded.Transparent&&!loaded.AutoSpeak&&loaded.VoiceBackend=="Windows","undo did not persist preferences");Layout();});
   Test("voice backend buttons persist selection without starting speech",()=>{Check(Store.Data.Settings.VoiceBackend=="Neural","natural voice is not default");Click("设置");Click("Windows 备用");Check(Store.Data.Settings.VoiceBackend=="Windows"&&new Store(dataDirectory).Data.Settings.VoiceBackend=="Windows","Windows fallback choice not saved");Click("自然语音 · 离线");Check(Store.Data.Settings.VoiceBackend=="Neural"&&new Store(dataDirectory).Data.Settings.VoiceBackend=="Neural","natural voice choice not saved");Check(Get<DispatcherTimer>("autoSpeech")==null||!Get<DispatcherTimer>("autoSpeech").IsEnabled,"backend switch scheduled hidden speech");Layout();});
  } catch(Exception e){failed++;Console.WriteLine("FAIL initialization: "+e);}
  finally {if(window!=null)window.Close();if(Directory.Exists(dataDirectory))Directory.Delete(dataDirectory,true);app.Shutdown();}
  Console.WriteLine("RESULT "+passed+" passed, "+failed+" failed");Environment.ExitCode=failed==0?0:1;
 }
}
